import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Random;
import java.util.Scanner;

/**
 * Boss AI for Quarto on CodinGame.
 * Strategy:
 * 1. If pieceToPlace creates a winning 4-in-a-row on any empty cell, place it there and WIN!
 * 2. When choosing a piece to give, NEVER give a piece that allows the opponent to immediately win on their next turn.
 * 3. Choose balanced placements and safe handovers.
 */
public class Boss {

    private static boolean isQuarto(int a, int b, int c, int d) {
        if (a < 0 || b < 0 || c < 0 || d < 0) return false;
        int commonOnes = (a & b & c & d);
        int commonZeros = (~a & ~b & ~c & ~d) & 0x0F;
        return (commonOnes | commonZeros) != 0;
    }

    private static boolean checkWin(int[][] grid) {
        // Rows
        for (int r = 0; r < 4; r++) {
            if (isQuarto(grid[r][0], grid[r][1], grid[r][2], grid[r][3])) return true;
        }
        // Columns
        for (int c = 0; c < 4; c++) {
            if (isQuarto(grid[0][c], grid[1][c], grid[2][c], grid[3][c])) return true;
        }
        // Diagonals
        if (isQuarto(grid[0][0], grid[1][1], grid[2][2], grid[3][3])) return true;
        if (isQuarto(grid[0][3], grid[1][2], grid[2][1], grid[3][0])) return true;
        return false;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Random rng = new Random();

        while (in.hasNextInt()) {
            int pieceToPlace = in.nextInt();

            int[][] board = new int[4][4];
            for (int r = 0; r < 4; r++) {
                for (int c = 0; c < 4; c++) {
                    board[r][c] = in.nextInt();
                }
            }

            int availableCount = in.nextInt();
            List<Integer> available = new ArrayList<>();
            for (int i = 0; i < availableCount; i++) {
                available.add(in.nextInt());
            }

            // Empty cells
            List<int[]> emptyCells = new ArrayList<>();
            for (int r = 0; r < 4; r++) {
                for (int c = 0; c < 4; c++) {
                    if (board[r][c] == -1) {
                        emptyCells.add(new int[]{r, c});
                    }
                }
            }

            // Turn 0: First player only picks a piece to give
            if (pieceToPlace == -1) {
                int pieceToGive = available.get(rng.nextInt(available.size()));
                System.out.println("-1 -1 " + pieceToGive + " Good luck!");
                continue;
            }

            // 1. Check if we can WIN immediately
            int bestR = -1;
            int bestC = -1;
            boolean foundWin = false;

            for (int[] cell : emptyCells) {
                int r = cell[0];
                int c = cell[1];
                board[r][c] = pieceToPlace;
                if (checkWin(board)) {
                    bestR = r;
                    bestC = c;
                    foundWin = true;
                    board[r][c] = -1;
                    break;
                }
                board[r][c] = -1;
            }

            // If no instant win, pick an empty cell (prefer center cells (1,1), (1,2), (2,1), (2,2))
            if (!foundWin) {
                int[][] priority = {
                        {1, 1}, {1, 2}, {2, 1}, {2, 2},
                        {0, 0}, {0, 3}, {3, 0}, {3, 3},
                        {0, 1}, {0, 2}, {1, 0}, {1, 3}, {2, 0}, {2, 3}, {3, 1}, {3, 2}
                };
                for (int[] p : priority) {
                    if (board[p[0]][p[1]] == -1) {
                        bestR = p[0];
                        bestC = p[1];
                        break;
                    }
                }
                if (bestR == -1 && !emptyCells.isEmpty()) {
                    int[] pick = emptyCells.get(0);
                    bestR = pick[0];
                    bestC = pick[1];
                }
            }

            // Temporarily apply our placement to evaluate which piece to give
            board[bestR][bestC] = pieceToPlace;

            // Recalculate remaining empty cells
            List<int[]> nextEmptyCells = new ArrayList<>();
            for (int r = 0; r < 4; r++) {
                for (int c = 0; c < 4; c++) {
                    if (board[r][c] == -1) {
                        nextEmptyCells.add(new int[]{r, c});
                    }
                }
            }

            // 2. Choose a piece to give that does NOT allow opponent to immediately win
            int chosenPieceToGive = -1;
            if (!available.isEmpty()) {
                List<Integer> safePieces = new ArrayList<>();
                for (int candidate : available) {
                    boolean givesWin = false;
                    for (int[] cell : nextEmptyCells) {
                        board[cell[0]][cell[1]] = candidate;
                        if (checkWin(board)) {
                            givesWin = true;
                            board[cell[0]][cell[1]] = -1;
                            break;
                        }
                        board[cell[0]][cell[1]] = -1;
                    }
                    if (!givesWin) {
                        safePieces.add(candidate);
                    }
                }

                if (!safePieces.isEmpty()) {
                    chosenPieceToGive = safePieces.get(rng.nextInt(safePieces.size()));
                } else {
                    // No safe piece, pick any available
                    chosenPieceToGive = available.get(rng.nextInt(available.size()));
                }
            }

            String msg = foundWin ? "QUARTO!" : "Your turn!";
            System.out.println(bestR + " " + bestC + " " + chosenPieceToGive + " " + msg);
        }
    }
}
